edits.text:
/* P7.13.1: visible validation target; no flashing or motion requirement. */
.ai-review-target{outline:2px solid #e99066;outline-offset:5px;border-radius:6px;scroll-margin-block:170px 100px;}
.ai-review-field-note{font-size:12px;line-height:1.6;color:#ffbe9e;margin-top:8px;overflow-wrap:anywhere;}
.ai-clock-hint{font-size:12px;line-height:1.6;overflow-wrap:anywhere;}

const hint=window.BxhPosterRefinements?window.BxhPosterRefinements.clockHint(result,"registration-open"):null;
const note=hint?`<p class="ai-clock-hint">已讀取報名時刻：<b>${esc(hint.time)}</b>${hint.channel?"｜管道："+esc(hint.channel):""}。${result.activity&&result.activity.registrationOpenAt?"請核對報名日期與時間。":"尚需確認報名日期；不會套入報到欄位。"}</p>`:"";
return note+`<details class="ai-poster-evidence"><summary>查看海報辨識文字與獎品（請人工核對）</summary><pre>${esc(result.posterText||"")}</pre></details>`;

if(applied.sourceMode==="poster-callable" && window.BxhPosterRefinements && d.venueName===activity.locationName){
  const candidate=window.BxhPosterRefinements.venueCandidate(d.venueName);
  const conflict=(applied.warnings||[]).some(w=>w.code==="source-conflict"&&/locationName|venue/.test(String(w.field||"")));
  if(candidate&&!conflict){
    const id="venue-proofread";
    if(aiCreateSuggestionSelection[id]===undefined)aiCreateSuggestionSelection[id]=false;
    add({id,origin:"recommended",title:"場地名稱疑似錯字",message:"辨識為「"+d.venueName+"」；常用場地候選是「"+candidate+"」。請對照海報，確定後才勾選。",value:candidate,apply:()=>{settingsFormDraft.venueName=candidate;settingsFormDraft.location=[candidate,settingsFormDraft.venueAddress].filter(Boolean).join("｜");}});
  }
}

// Legacy name retained for callers; draft pickers now preserve every minute.
if(!value)return true;
if(window.BxhPosterRefinements)return window.BxhPosterRefinements.preciseTime(value);
return /^(?:[01]\d|2[0-3]):[0-5]\d$/.test(String(value)) ||
  /^\d{4}-\d{2}-\d{2}T(?:[01]\d|2[0-3]):[0-5]\d:00\+08:00$/.test(String(value));

if(activity.registrationOpenAt && !openCompatible) warnings.push("報名開放 "+String(activity.registrationOpenAt).slice(11,16)+" 格式無效，因此不自動套用；不會四捨五入。");
if(activity.registrationCloseAt && !closeCompatible) warnings.push("報名截止 "+String(activity.registrationCloseAt).slice(11,16)+" 格式無效，因此不自動套用。");
if(event.checkInStart && !checkinCompatible) warnings.push("報到時間 "+event.checkInStart+" 格式無效，因此不自動套用。");
if(event.startAt && !startCompatible) warnings.push("開賽時間 "+event.startAt+" 格式無效，因此不自動套用。");

function aiCreateRegistrationClockHint(field){
  const result=aiCreateLastApplied&&aiCreateLastApplied.result;
  if(!window.BxhPosterRefinements||!result)return null;
  return window.BxhPosterRefinements.clockHint(result,field==="registrationOpenAt"?"registration-open":"registration-close");
}
let aiCreateFocusGeneration=0;
function aiCreateFocusIssue(code){
  if(!window.BxhPosterRefinements||!window.BxhPosterRefinements.targetId(code)||!hasAdminAccess())return;
  syncSettingsDraftFromDom();syncRegistrationDraftFromDom();
  const room=state,roomId=state&&state.id,uid=firebaseUser&&firebaseUser.uid,generation=++aiCreateFocusGeneration;
  if(activeTab!=="settings"){activeTab="settings";render();}
  // closeModal/render restore scroll for up to 180ms; navigate after that, not underneath it.
  setTimeout(()=>{
    if(generation!==aiCreateFocusGeneration||room!==state||roomId!==(state&&state.id)||uid!==(firebaseUser&&firebaseUser.uid)||activeTab!=="settings"||!hasAdminAccess())return;
    const report=aiCreateReviewReport();
    const issue=report.blockers.find(x=>x.code===code);
    const target=issue?code:"review";
    window.BxhPosterRefinements.focusField(target,issue?issue.title+"："+issue.message:"請核對並確認 AI 提醒。",document);
  },220);
}

if(result.sourceMode==="poster-callable" && window.BxhPosterRefinements){
  for(const [kind,field,label] of [["registration-open","registrationOpenAt","報名開放"],["registration-close","registrationCloseAt","報名截止"]]){
    const hint=window.BxhPosterRefinements.clockHint(result,kind);
    if(hint&&!rd[field])add(infos,"poster-clock:"+field,label+"時刻已讀取",hint.time+(hint.channel?"｜管道："+hint.channel:"")+"。請確認完整報名日期；這不是報到時間，不會套入報到欄位。");
  }
}
